import json, re, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
T = {'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'h','ц':'c','ч':'ch','ш':'sh','щ':'sch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'}
def slug(s): return re.sub(r'[^a-z0-9]+','-',''.join(T.get(c,c) for c in s.lower())).strip('-')[:40]
CR='https://img1.creatium.ru/disk2/'
items, fetch = [], []
def add(cat, sub, subName, name, unit, note, src, img_url=None, prefix='', fit='contain', extra=None):
    sid = prefix + slug(name)
    it = {'id': f'{cat}-{sid}', 'cat': cat, 'sub': sub, 'subName': subName, 'name': name, 'price': None, 'unit': unit,
          'img': f'img/p/{sid}.jpg' if img_url else '', 'fit': fit, 'note': note, 'src': src}
    if extra: it.update(extra)
    items.append(it)
    if img_url: fetch.append((img_url, f'site/img/p/{sid}.jpg'))
