for p in ['tools/catalog.json','bot/catalog.json']:
    fp=os.path.join(ROOT,p); c=json.load(open(fp,encoding='utf-8'))
    have={i['id'] for i in c['items']}
    new=[i for i in items if i['id'] not in have]
    assert len({i['id'] for i in items})==len(items),'дубли id'
    c['items']+=new
    open(fp,'w',encoding='utf-8').write(json.dumps(c,ensure_ascii=False))
    print(p,'+',len(new))
